using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class TimberRelayChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var s=new ResourceState();s.Ensure("tree",VillageResource.Wood);s.Harvest(2,"tree",3);float remaining=s.Find("tree").remaining;
  Check(!s.TransferTimber(2,2)&&!s.TransferTimber(-1,1)&&s.TransferTimber(2,1),"Timber transfer gates failed");
  Check(s.cargo[2].amount==0&&s.cargo[1].amount==3&&s.Find("tree").remaining==remaining&&s.wood==0&&s.Valid(),"Transfer created stock or lost finite cargo");
  Check(!s.TransferTimber(2,1),"Empty donor duplicated cargo");s.Recover(1);Check(s.Find("tree").remaining==12&&s.wood==0,"Canceled relay lost wood");
  var season=new SliceState();string before=JsonUtility.ToJson(season);CreationBookText.Read(season,CreationBookSection.Provisions,1);Check(before==JsonUtility.ToJson(season),"Book invented a relay");
  season.Hybrid.time=10;season.timberRelay=new TimberRelayMemory{count=1,cutter=2,carrier=1,source="tree",amount=3,time=10};Check(season.Valid()&&JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(season)).Valid(),"Relay did not round-trip");season.timberRelay.carrier=2;Check(!season.Valid(),"Solo work accepted as cooperation");season.timberRelay.carrier=1;season.timberRelay.amount=4;Check(!season.Valid(),"Oversize relay accepted");
  Debug.Log("BWVR_TIMBER_RELAY_MODEL_PASS: finite transfer, same/invalid/empty donor guards, recoverable cargo, read-only Book, bounded saved outcome");
 }
 public static void VerifyRuntime(Action<SliceState> prepare=null,Action<SliceState> arrived=null){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=world.Navigation;Check(!nav.TreeNavigationPending,"Wait for tree navigation");var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var actors=world.Gatherers;var positions=actors.Select(a=>a.transform.position).ToArray();var rotations=actors.Select(a=>a.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var worker=actors[2];var helper=actors[1];SliceState test=null;GameObject blocker=null;
  void Tick(bool help=true){test.Hybrid.time+=.05f;if(worker.Active)worker.Tick(.05f,test.paused);if(help)helper.Tick(.05f,test.paused);}
  void StageHelper(){for(int k=0;k<24;k++){var at=worker.transform.position+Quaternion.Euler(0,k*15,0)*Vector3.forward*nav.Scale*9;if(!helper.GetComponent<IslandNavigator>().CanPlace(at,out var ground))continue;helper.transform.position=ground;helper.transform.LookAt(new Vector3(worker.transform.position.x,ground.y,worker.transform.position.z));helper.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();if(world.ProvisionVisible(helper.GetComponent<VillagerSocial>(),worker.transform.position,worker.transform))return;}throw new Exception("No clear helper position");}
  void HarvestNext(){worker.Cancel();helper.Cancel();foreach(var a in actors)a.transform.position=world.StoreApproach+Vector3.up*nav.Scale*600;Check(worker.GetComponent<IslandNavigator>().CanPlace(world.StoreApproach,out var at),"No worker stage");worker.transform.position=at;worker.GetComponent<IslandNavigator>().ResetRoute();var source=world.sources.Where(s=>s.kind==VillageResource.Wood&&!world.State.Find(s.id).felled&&world.Available(s)&&world.Safe(s)).OrderBy(s=>(s.approach-at).sqrMagnitude).FirstOrDefault();Check(source!=null&&worker.TryBegin(source),"No standing-tree task");for(int i=0;i<2400&&worker.Current!=VillagerResourceGathering.Phase.Harvest;i++)Tick(false);Check(worker.Current==VillagerResourceGathering.Phase.Harvest,"Worker did not reach tree");StageHelper();for(int i=0;i<200&&worker.Current==VillagerResourceGathering.Phase.Harvest;i++)Tick(false);Check(worker.Current==VillagerResourceGathering.Phase.OfferWood,"Actual equipped harvest did not offer timber: "+worker.Current);}
  try{
   god.Interrupt("Timber relay QA");foreach(var a in actors){a.Cancel();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();a.GetComponent<VillagerSocial>().ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(a.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(a.GetComponent<VillagerRoutine>());a.GetComponent<CarryItem>().held=false;}
   test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};test.resources=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(world.State));test.Resources.wood=8;test.Resources.resin=4;test.Resources.wheat=20;test.Resources.freshFood=test.Resources.exposedWheat=0;for(int i=0;i<3;i++)test.Tools.Practice(0,1);Check(test.Tools.OfferDelivery(test.Resources,0,2,VillageTool.BoundAxe,0,Vector3.zero)&&test.Tools.ReceiveDelivery(test.Resources,ToolDeliverySource.Player),"Equipment fixture failed");field.SetValue(slice,test);god.NewSeason();world.ResetWorld();prepare?.Invoke(test);god.transform.position=world.StoreApproach+Vector3.up*nav.Scale*800;slice.SetSanctuaryOpen(false);
   HarvestNext();string sourceId=worker.Source.id;float stock=test.Resources.wood,remaining=test.Resources.Find(sourceId).remaining;Check(test.Tools.delivery.proof?.used==true,"Tool use proof missing");
   helper.GetComponent<CarryItem>().held=true;Check(!helper.TryTimberRelay(),"Player-held helper recruited");helper.GetComponent<CarryItem>().held=false;
   var friendship=helper.GetComponent<VillagerSocial>().Memory;friendship.RememberPeer("villager-2",false,test.Hybrid.time);Check(!helper.TryTimberRelay(),"Recently harmed neighbor forced to help");friendship.peers=Array.Empty<VillagerBond>();
   blocker=new GameObject("QA relay sightline occluder",typeof(BoxCollider));blocker.transform.position=(worker.transform.position+helper.transform.position)*.5f+Vector3.up*nav.Scale*2;blocker.GetComponent<BoxCollider>().size=new Vector3(2,8,2)*nav.Scale;Physics.SyncTransforms();Check(!helper.TryTimberRelay(),"Occluded helper recruited");UnityEngine.Object.DestroyImmediate(blocker);blocker=null;
   // The ordinary idle gathering selector accepts the opportunity, with no forced reservation.
   for(int i=0;i<150&&!helper.Active;i++)helper.Tick(.05f,false);Check(helper.Current==VillagerResourceGathering.Phase.RelayApproach,"Idle helper did not choose relay: helper="+helper.Current+" worker="+worker.Current+" free="+typeof(VillagerResourceGathering).GetProperty("RelayFree",F).GetValue(helper)+" visible="+world.ProvisionVisible(helper.GetComponent<VillagerSocial>(),worker.transform.position,worker.transform)+" reachable="+slice.GetComponentInChildren<IslandDiscoveries>().Reachable(helper.transform.position,worker.transform.position,nav.villager));Check(!actors[0].TryTimberRelay(),"Second helper stole reserved work");helper.Cancel();Check(worker.Current==VillagerResourceGathering.Phase.OfferWood&&test.Resources.cargo[2].amount==3&&worker.Source.owner==worker,"Canceled approach stole donor cargo");Check(helper.TryTimberRelay(),"Approach cancellation stranded invitation");var phase=helper.Current;worker.Tick(5,true);helper.Tick(5,true);Check(helper.Current==phase&&test.Resources.cargo[2].amount==3&&(test.timberRelay==null||test.timberRelay.count==0),"Paused relay changed cargo/history");
   for(int i=0;i<500&&helper.Current!=VillagerResourceGathering.Phase.Carry;i++)Tick();Check(helper.Current==VillagerResourceGathering.Phase.Carry&&test.Resources.cargo[1].amount==3&&test.Resources.cargo[2].amount==0&&worker.Current==VillagerResourceGathering.Phase.Idle&&helper.Source.owner==helper,"Physical handoff did not transfer exclusive cargo: helper="+helper.Current+" worker="+worker.Current);Check(test.Resources.wood==stock&&test.Resources.Find(sourceId).remaining==remaining&&(test.timberRelay==null||test.timberRelay.count==0),"Handoff minted success or resources");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();world.ResetWorld();test.developmentFocus=test.observeWithoutFoodWork=true;friendship=helper.GetComponent<VillagerSocial>().Memory;Check(test.Valid()&&test.Resources.Find(sourceId).remaining==remaining+3&&test.Resources.wood==stock&&(test.timberRelay==null||test.timberRelay.count==0)&&!test.Tools.delivery.proof.stored&&test.Resources.cargo.All(c=>c.amount==0),"Reloaded carrier credited/lost cargo");
   // A fresh standing-tree load completes through native carrying and storage.
   HarvestNext();for(int i=0;i<150&&!helper.Active;i++)helper.Tick(.05f,false);for(int i=0;i<4000&&(test.timberRelay==null||test.timberRelay.count==0);i++)Tick();var record=test.timberRelay;Check(record?.count==1&&record.cutter==2&&record.carrier==1&&record.amount==3&&test.Resources.wood==stock+3,"Native shared delivery failed: worker="+worker.Current+" helper="+helper.Current);Check(test.Resources.deliveries==original.Resources.deliveries+1,"Relay deposited more than once");Check(test.Tools.learners[1].axeUses==0&&test.Tools.learners[2].axeUses==2&&!test.Hybrid.receipt.eligible&&test.Tools.delivery.source==ToolDeliverySource.Player&&test.Tools.delivery.proof.stored,"Work attribution / tool produce proof wrong");Check(friendship.Peer("villager-2")?.good==1&&worker.GetComponent<VillagerSocial>().Memory.Peer("villager-1")?.good==1,"Completed cooperation not remembered mutually");
   string json=JsonUtility.ToJson(record);for(int i=0;i<40;i++)Tick(false);Check(JsonUtility.ToJson(test.timberRelay)==json&&test.Resources.wood==stock+3,"Completed relay repeated");var page=CreationBookText.Read(test,CreationBookSection.Provisions,1);Check(page.text.Contains("Wood stored 3")&&page.text.Contains("Completed relays 1"),"Book disagrees with delivery");
   HarvestNext();for(int i=0;i<160&&worker.Current==VillagerResourceGathering.Phase.OfferWood;i++)Tick(false);Check(worker.Current==VillagerResourceGathering.Phase.Carry&&test.Resources.cargo[2].amount==3&&!helper.Active&&JsonUtility.ToJson(test.timberRelay)==json,"Unaccepted offer did not fall back to solo carry");worker.Cancel();Check(test.Resources.wood==stock+3,"Solo cancellation fabricated stock");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();world.ResetWorld();Check(test.Valid()&&test.timberRelay.count==1&&test.timberRelay.cutter==2&&test.timberRelay.carrier==1&&test.timberRelay.amount==3&&test.Resources.wood==stock+3,"Native save lost shared outcome");
   arrived?.Invoke(test);Debug.Log("BWVR_TIMBER_RELAY_RUNTIME_PASS: real felling, voluntary idle helper, sightline/held/hostility/pause gates, one native approach/take/carry/deposit, exact finite stock, approach cancellation, interrupted-load recovery, solo fallback, separate work/haul attribution, mutual peer memory, no creature credit and saved Book result");
  }finally{if(blocker!=null)UnityEngine.Object.DestroyImmediate(blocker);foreach(var a in actors)a.Cancel();god.Interrupt("Timber relay QA complete");field.SetValue(slice,original);god.NewSeason();world.ResetWorld();god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<actors.Length;i++){actors[i].GetComponent<CarryItem>().held=false;actors[i].transform.SetPositionAndRotation(positions[i],rotations[i]);actors[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
